//go:build windows

package wintray

import (
	"embed"

	"github.com/alexal46372-maker/ExchangeChecker/internal/trayui"
	"github.com/alexal46372-maker/ExchangeChecker/internal/winapi"
)

// icoFiles: the .ico files generated by tools/mkres (phase 11, PLAN §12
// p.144, CHK-TRAY-49).
//
//go:embed icons/*.ico
var icoFiles embed.FS

// icoSmall / icoLarge: the icon sizes in 96-dpi units (px scales them:
// 16/32 at 96 dpi, 24/48 at 144 dpi).
const (
	icoSmall = 16
	icoLarge = 32
)

type icoKey struct {
	name string
	size int32
}

// icons is a cache of HICONs made from the embedded .ico files.
type icons struct{ m map[icoKey]uintptr }

// get is the tray icon of kind k (small icon size of the current DPI).
func (ic *icons) get(k trayui.Icon) uintptr { return ic.ico(trayui.StateIco(k), px(icoSmall)) }

// ico is the HICON of name at size pixels (0 if it cannot be made).
func (ic *icons) ico(name string, size int32) uintptr {
	if ic.m == nil {
		ic.m = map[icoKey]uintptr{}
	}
	k := icoKey{name, size}
	if h, ok := ic.m[k]; ok {
		return h
	}
	b, err := icoFiles.ReadFile("icons/" + name + ".ico")
	if err != nil {
		return 0
	}
	p, err := trayui.DecodeICO(b, int(size))
	if err != nil {
		return 0
	}
	h, err := winapi.CreateIconFromPixels(int(size), int(size), p)
	if err != nil {
		return 0
	}
	ic.m[k] = h
	return h
}

func (ic *icons) free() {
	for _, h := range ic.m {
		winapi.DestroyIcon(h)
	}
	ic.m = nil
}

// uiIcons: the window, navigation and card icons (UI thread, process
// lifetime).
var uiIcons icons

// setWindowIcons gives a top-level window the app icon (title bar, Alt+Tab).
func setWindowIcons(hwnd uintptr) {
	winapi.SendMessage(hwnd, winapi.WM_SETICON, winapi.ICON_SMALL, uiIcons.ico(trayui.IcoApp, px(icoSmall)))
	winapi.SendMessage(hwnd, winapi.WM_SETICON, winapi.ICON_BIG, uiIcons.ico(trayui.IcoApp, px(icoLarge)))
}

